import os
import sqlite3

# List all db files
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith('.db'):
            print(f'Found DB: {os.path.join(root, f)}')
            try:
                conn = sqlite3.connect(os.path.join(root, f))
                cursor = conn.cursor()
                cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
                tables = cursor.fetchall()
                print(f'  Tables: {tables}')
                for table in tables:
                    cursor.execute(f"SELECT COUNT(*) FROM {table[0]};")
                    count = cursor.fetchone()[0]
                    cursor.execute(f"SELECT MIN(Date), MAX(Date) FROM {table[0]};")
                    dates = cursor.fetchone()
                    print(f'    {table[0]}: {count} rows, dates: {dates}')
                conn.close()
            except Exception as e:
                print(f'  Error: {e}')

print('\n--- Checking context for other files ---')
for root, dirs, files in os.walk('context'):
    for f in files:
        if f.endswith('.csv') or f.endswith('.db') or f.endswith('.json'):
            print(os.path.join(root, f))

